    // V095_DEADLINE_CHANGE: pending edits do not resend alerts; confirmed edits
    // require fresh lecturer approval, and other accounts cannot change deadlines.
    [Fact]
    public async Task StudentChangesPendingDeadline_NoNewLecturerNotification_ThenLecturerConfirms()
    {
        using var app = new TestApp();
        await app.SeedAsync();
        using (var scope = app.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<StudentProjectsDbContext>();
            var m = await db.Milestones.SingleAsync(x => x.Id == MilestoneA);
            m.ProposedByStudent = true;
            m.ProposalStatus = "PENDING_REVIEW";
            db.AuditEntries.Add(new AuditEntry { ActorUserId = StudentA,
                EntityName = "Milestone", EntityId = MilestoneA, Action = "MILESTONE_PROPOSED" });
            await db.SaveChangesAsync();
        }
        using var student = await Login(app, "student-a@v09.test");
        using var lecturer = await Login(app, "lecturer-a@v09.test");
        var path = $"/api/v1/v07/milestones/{MilestoneA}/deadline";
        var newDay = DateTimeOffset.UtcNow.AddDays(15);
        Assert.Equal(HttpStatusCode.OK, (await student.PutAsJsonAsync(path,
            new { deadlineAt = newDay })).StatusCode);
        using (var scope = app.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<StudentProjectsDbContext>();
            var m = await db.Milestones.SingleAsync(x => x.Id == MilestoneA);
            Assert.Equal("PENDING_REVIEW", m.ProposalStatus);
            Assert.Single(await db.AuditEntries.Where(a => a.EntityId == MilestoneA &&
                a.Action == "MILESTONE_DEADLINE_UPDATED_PENDING").ToListAsync());
            Assert.Empty(await db.AuditEntries.Where(a => a.EntityId == MilestoneA &&
                a.Action == "MILESTONE_DEADLINE_CHANGE_REQUESTED").ToListAsync());
        }
        using (var notices = (await lecturer.GetFromJsonAsync<JsonDocument>("/api/v1/v08/notifications"))!)
        {
            var planNotices = notices.RootElement.GetProperty("items").EnumerateArray()
                .Where(x => x.GetProperty("type").GetString()!.StartsWith("V08:PLAN:")).ToArray();
            Assert.Single(planNotices); // original proposal, no extra notice
        }
        Assert.Equal(HttpStatusCode.OK, (await lecturer.PostAsJsonAsync(
            $"/api/v1/v07/milestones/{MilestoneA}/proposal-review",
            new { isConfirmed = true, feedback = "" })).StatusCode);
    }

    [Fact]
    public async Task ConfirmedDeadlineChange_RequiresReapproval_AndNotifiesLecturerOnlyOnce()
    {
        using var app = new TestApp();
        await app.SeedAsync();
        using var student = await Login(app, "student-a@v09.test");
        using var lecturer = await Login(app, "lecturer-a@v09.test");
        var path = $"/api/v1/v07/milestones/{MilestoneA}/deadline";
        var newDay = DateTimeOffset.UtcNow.AddDays(20);
        Assert.Equal(HttpStatusCode.OK, (await student.PutAsJsonAsync(path,
            new { deadlineAt = newDay })).StatusCode);
        // Same calendar day cannot send a second confirmation request.
        Assert.Equal(HttpStatusCode.OK, (await student.PutAsJsonAsync(path,
            new { deadlineAt = newDay })).StatusCode);
        using (var scope = app.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<StudentProjectsDbContext>();
            Assert.Equal("PENDING_REVIEW", (await db.Milestones.SingleAsync(x => x.Id == MilestoneA)).ProposalStatus);
            Assert.Single(await db.AuditEntries.Where(a => a.EntityId == MilestoneA &&
                a.Action == "MILESTONE_DEADLINE_CHANGE_REQUESTED").ToListAsync());
        }
        Assert.Equal(HttpStatusCode.Conflict, (await student.PostAsJsonAsync(
            $"/api/v1/v07/milestones/{MilestoneA}/progress",
            new { percentComplete = 10, workDone = "Before approval", note = "" })).StatusCode);
        using (var notifications = (await lecturer.GetFromJsonAsync<JsonDocument>("/api/v1/v08/notifications"))!)
        {
            var alerts = notifications.RootElement.GetProperty("items").EnumerateArray()
                .Where(x => x.GetProperty("message").GetString()!.Contains("đổi ngày nộp")).ToArray();
            Assert.Single(alerts);
            Assert.Equal($"/milestones?projectId={ProjectA:D}&milestoneId={MilestoneA:D}",
                alerts[0].GetProperty("targetUrl").GetString());
        }
        Assert.Equal(HttpStatusCode.OK, (await lecturer.PostAsJsonAsync(
            $"/api/v1/v07/milestones/{MilestoneA}/proposal-review",
            new { isConfirmed = true, feedback = "" })).StatusCode);
        using (var scope = app.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<StudentProjectsDbContext>();
            Assert.Equal("CONFIRMED", (await db.Milestones.SingleAsync(x => x.Id == MilestoneA)).ProposalStatus);
        }
    }

    [Fact]
    public async Task DeadlineEdits_BlockOtherStudentsLecturersAdminAndSubmittedMilestones()
    {
        using var app = new TestApp();
        await app.SeedAsync();
        using var other = await Login(app, "student-b@v09.test");
        using var lecturer = await Login(app, "lecturer-a@v09.test");
        using var admin = await Login(app, "admin@v09.test");
        using var owner = await Login(app, "student-a@v09.test");
        var path = $"/api/v1/v07/milestones/{MilestoneA}/deadline";
        var input = new { deadlineAt = DateTimeOffset.UtcNow.AddDays(10) };
        Assert.Equal(HttpStatusCode.Forbidden, (await other.PutAsJsonAsync(path,input)).StatusCode);
        Assert.Equal(HttpStatusCode.Forbidden, (await lecturer.PutAsJsonAsync(path,input)).StatusCode);
        Assert.Equal(HttpStatusCode.Forbidden, (await admin.PutAsJsonAsync(path,input)).StatusCode);
        using (var scope = app.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<StudentProjectsDbContext>();
            (await db.Milestones.SingleAsync(x => x.Id == MilestoneA)).Status = MilestoneStatus.SUBMITTED;
            await db.SaveChangesAsync();
        }
        Assert.Equal(HttpStatusCode.Conflict, (await owner.PutAsJsonAsync(path,input)).StatusCode);
    }
